@id("guardrail.archived-read-only")
forbid (principal, action in SPOH::Action::"Write", resource)
when { context.eventPhase == "ARCHIVED" };

@id("guardrail.capture-window")
forbid (principal, action in SPOH::Action::"Capture", resource)
unless
{
  context.eventPhase == "LIVE" ||
  context.eventPhase == "REHEARSAL" ||
  (context.eventPhase == "CLOSED" && context.lateSyncAllowed)
};

@id("guardrail.grant-below-own-rank")
forbid (
  principal is SPOH::Membership,
  action in [SPOH::Action::"People.AssignRole", SPOH::Action::"People.Invite"],
  resource
)
unless { context has grantedRank && context.grantedRank < principal.rank };

@id("guardrail.inactive-member")
forbid (principal is SPOH::Membership, action, resource)
unless { principal.active && principal.person.active };

@id("guardrail.inactive-person")
forbid (principal is SPOH::Person, action, resource)
unless { principal.active };

@id("guardrail.not-on-yourself")
forbid (
  principal is SPOH::Membership,
  action in
    [SPOH::Action::"People.Update",
     SPOH::Action::"People.Deactivate",
     SPOH::Action::"People.AssignRole"],
  resource is SPOH::Membership
)
when { resource == principal };

@id("guardrail.outrank-target")
forbid (
  principal is SPOH::Membership,
  action in
    [SPOH::Action::"People.Update",
     SPOH::Action::"People.Deactivate",
     SPOH::Action::"People.AssignRole"],
  resource is SPOH::Membership
)
when { resource.rank >= principal.rank };

@id("guardrail.same-event")
forbid (principal is SPOH::Membership, action, resource)
unless { resource in principal.event };

@id("guardrail.structure-frozen-when-live")
forbid (
  principal is SPOH::Membership,
  action == SPOH::Action::"Structure.Change",
  resource
)
when { ["LIVE", "CLOSED", "ARCHIVED"].contains(context.eventPhase) };

@id("platform.admin")
permit (principal is SPOH::Person, action in SPOH::Action::"Platform", resource)
when { principal.platformAdmin };

@id("platform.archived-reader")
permit (principal is SPOH::Membership, action, resource)
when { context.eventPhase == "ARCHIVED" && principal.person.platformAdmin }
unless { action in SPOH::Action::"Write" };

@id("platform.assign-any-role")
permit (
  principal is SPOH::Person,
  action in [SPOH::Action::"People.Invite", SPOH::Action::"People.AssignRole"],
  resource
)
when { principal.platformAdmin };

@id("self.alert-ack")
permit (
  principal is SPOH::Membership,
  action == SPOH::Action::"Alert.Ack",
  resource is SPOH::LostPersonAlert
);

@id("self.announcement-ack")
permit (
  principal is SPOH::Membership,
  action == SPOH::Action::"Announcement.Ack",
  resource is SPOH::Announcement
)
when
{
  (if resource has targetRole
   then resource.targetRole == principal.role.catalogueRole
   else true) &&
  (if resource has targetStation
   then principal.assignedStations.contains(resource.targetStation)
   else true) &&
  (if resource has targetDay
   then principal.workingDays.contains(resource.targetDay)
   else true)
};

@id("self.attendance-submit")
permit (
  principal is SPOH::Membership,
  action == SPOH::Action::"Attendance.Submit",
  resource is SPOH::EventDay
);

@id("self.briefing")
permit (
  principal is SPOH::Membership,
  action == SPOH::Action::"Briefing.Complete",
  resource is SPOH::BriefingSlot
)
when { resource has briefer && resource.briefer == principal };

@id("self.check-in-conditions")
forbid (
  principal is SPOH::Membership,
  action == SPOH::Action::"Shift.CheckIn",
  resource is SPOH::ShiftAssignment
)
unless
{
  principal.attendanceVerifiedToday &&
  (resource.shiftRunning || context.eventPhase == "REHEARSAL")
};

@id("self.own-shift")
permit (
  principal is SPOH::Membership,
  action in [SPOH::Action::"Shift.CheckIn", SPOH::Action::"Swap.Request"],
  resource is SPOH::ShiftAssignment
)
when { resource.membership == principal };

@id("self.read")
permit (
  principal is SPOH::Membership,
  action == SPOH::Action::"Self.Read",
  resource is SPOH::Membership
)
when { resource == principal };

@id("station-scope.capture")
forbid (
  principal is SPOH::Membership,
  action in SPOH::Action::"Capture",
  resource is SPOH::Station
)
unless
{
  principal.role.anyStation ||
  principal.onShiftStations.contains(resource) ||
  (context.eventPhase == "REHEARSAL" && principal.assignedStations.contains(resource))
};

@id("station-scope.ic-own-stations")
forbid (
  principal is SPOH::Membership,
  action in [SPOH::Action::"Roster.ReadStation", SPOH::Action::"Announcement.SendStation"],
  resource is SPOH::Station
)
unless { principal.rank >= 30 || principal.assignedStations.contains(resource) };
